/**
 * Form - printable and fillable form fields for React PDF documents.
 *
 * @registryTitle PDF Form
 * @registryDescription Printable fields plus opt-in native AcroForm text, checkbox, select, list, and fieldset wrappers.
 * @registryCategory forms
 * @registryDemos basic=Basic, checkbox=Checkbox, native=Native
 */

import * as React from "react";
import {
  Checkbox,
  FieldSet,
  List as ReactPdfList,
  Select,
  TextInput,
  View,
  Text,
  StyleSheet,
} from "@react-pdf/renderer";
import type { Style } from "@react-pdf/types";
import {
  clampPdfNumber,
  createPdfTextStyle,
  formatPdfValue,
  getPdfPrimitiveProps,
  isPdfNodeEmpty,
  mergePdfStyles,
  type PdfPrimitiveProps,
  type PdfStyleInput,
  usePdfTheme,
} from "@/lib/pdf-theme";

export interface PdfFormProps extends PdfPrimitiveProps {
  children: React.ReactNode;
  columns?: 1 | 2;
  style?: PdfStyleInput;
}

export interface PdfFormFieldProps extends PdfPrimitiveProps {
  label: string;
  value?: React.ReactNode;
  placeholder?: string;
  lines?: number;
  style?: PdfStyleInput;
}

export interface PdfCheckboxFieldProps extends PdfPrimitiveProps {
  label: string;
  checked?: boolean | "indeterminate";
  style?: PdfStyleInput;
}

export interface PdfNativeFieldCommonProps extends PdfPrimitiveProps {
  name?: string;
  required?: boolean;
  noExport?: boolean;
  readOnly?: boolean;
  value?: number | string;
  defaultValue?: number | string;
}

export interface PdfTextInputFormat {
  type:
    | "date"
    | "time"
    | "percent"
    | "number"
    | "zip"
    | "zipPlus4"
    | "phone"
    | "ssn";
  param?: string;
  nDec?: number;
  sepComma?: boolean;
  negStyle?: "MinusBlack" | "Red" | "ParensBlack" | "ParensRed";
  currency?: string;
  currencyPrepend?: boolean;
}

export interface PdfFieldSetProps extends PdfPrimitiveProps {
  name: string;
  children: React.ReactNode;
  label?: React.ReactNode;
  style?: PdfStyleInput;
  labelStyle?: PdfStyleInput;
}

export interface PdfTextInputFieldProps extends PdfNativeFieldCommonProps {
  label?: React.ReactNode;
  description?: React.ReactNode;
  align?: "left" | "center" | "right";
  multiline?: boolean;
  password?: boolean;
  noSpell?: boolean;
  format?: PdfTextInputFormat;
  fontSize?: number;
  maxLength?: number;
  lines?: number;
  style?: PdfStyleInput;
  labelStyle?: PdfStyleInput;
  inputStyle?: PdfStyleInput;
}

export interface PdfCheckboxInputFieldProps extends PdfNativeFieldCommonProps {
  label?: React.ReactNode;
  checked?: boolean;
  backgroundColor?: string;
  borderColor?: string;
  onState?: string;
  offState?: string;
  xMark?: boolean;
  style?: PdfStyleInput;
  labelStyle?: PdfStyleInput;
  checkboxStyle?: PdfStyleInput;
}

export interface PdfSelectFieldProps extends PdfNativeFieldCommonProps {
  label?: React.ReactNode;
  select?: string[];
  sort?: boolean;
  edit?: boolean;
  multiSelect?: boolean;
  noSpell?: boolean;
  style?: PdfStyleInput;
  labelStyle?: PdfStyleInput;
  inputStyle?: PdfStyleInput;
}

export type PdfListInputFieldProps = PdfSelectFieldProps;

function getNativeFieldProps({
  id,
  debug,
  fixed,
  break: pageBreak,
  minPresenceAhead,
  name,
  required,
  noExport,
  readOnly,
  value,
  defaultValue,
}: PdfNativeFieldCommonProps) {
  return {
    id,
    debug,
    fixed,
    break: pageBreak,
    minPresenceAhead,
    name,
    required,
    noExport,
    readOnly,
    value,
    defaultValue,
  };
}

export function PdfForm({
  children,
  columns = 1,
  style,
  ...primitiveProps
}: PdfFormProps) {
  const styles = StyleSheet.create({
    root: {
      flexDirection: columns === 2 ? "row" : "column",
      flexWrap: "wrap",
      gap: 8,
    } as Style,
  });
  return (
    <View
      {...getPdfPrimitiveProps(primitiveProps)}
      style={mergePdfStyles(styles.root, style)}
    >
      {children}
    </View>
  );
}

function NativeFieldLabel({
  children,
  style,
}: {
  children?: React.ReactNode;
  style?: PdfStyleInput;
}) {
  const theme = usePdfTheme();
  const styles = StyleSheet.create({
    label: {
      ...createPdfTextStyle(theme, { size: "xs", tone: "muted" }),
      marginBottom: 4,
      textTransform: "uppercase",
    } as Style,
  });
  if (isPdfNodeEmpty(children)) return null;
  return <Text style={mergePdfStyles(styles.label, style)}>{children}</Text>;
}

export function PdfFormField({
  label,
  value,
  placeholder = "",
  lines = 1,
  style,
  ...primitiveProps
}: PdfFormFieldProps) {
  const theme = usePdfTheme();
  const safeLines = clampPdfNumber(lines, 1, 1, 12);
  const formattedValue = formatPdfValue(value);
  const hasValue = !isPdfNodeEmpty(formattedValue);
  const styles = StyleSheet.create({
    field: { flex: 1, marginBottom: theme.spacing.sm } as Style,
    label: {
      ...createPdfTextStyle(theme, { size: "xs", tone: "muted" }),
      marginBottom: 4,
      textTransform: "uppercase",
    } as Style,
    box: {
      borderColor: theme.colors.border,
      borderRadius: theme.radii.sm,
      borderWidth: 1,
      minHeight: safeLines * 18,
      padding: 6,
    } as Style,
    value: createPdfTextStyle(theme, {
      size: "sm",
      tone: hasValue ? "default" : "muted",
    }),
  });
  return (
    <View
      {...getPdfPrimitiveProps(primitiveProps)}
      style={mergePdfStyles(styles.field, style)}
    >
      <Text style={styles.label}>{label}</Text>
      <View style={styles.box}>
        <Text style={styles.value}>
          {hasValue ? formattedValue : placeholder}
        </Text>
      </View>
    </View>
  );
}

export function PdfCheckboxField({
  label,
  checked = false,
  style,
  ...primitiveProps
}: PdfCheckboxFieldProps) {
  const theme = usePdfTheme();
  const styles = StyleSheet.create({
    row: {
      alignItems: "center",
      flexDirection: "row",
      gap: 6,
      marginBottom: theme.spacing.sm,
    } as Style,
    box: {
      alignItems: "center",
      borderColor: theme.colors.border,
      borderWidth: 1,
      height: 10,
      justifyContent: "center",
      width: 10,
    } as Style,
    check: createPdfTextStyle(theme, {
      color: theme.colors.primary,
      fontSize: 8,
    }),
    label: createPdfTextStyle(theme, { size: "sm" }),
  });
  return (
    <View
      {...getPdfPrimitiveProps(primitiveProps)}
      style={mergePdfStyles(styles.row, style)}
    >
      <View style={styles.box}>
        {checked ? (
          <Text style={styles.check}>
            {checked === "indeterminate" ? "-" : "\u2713"}
          </Text>
        ) : null}
      </View>
      <Text style={styles.label}>{label}</Text>
    </View>
  );
}

export function PdfFieldSet({
  name,
  children,
  label,
  style,
  labelStyle,
  ...primitiveProps
}: PdfFieldSetProps) {
  const theme = usePdfTheme();
  const styles = StyleSheet.create({
    fieldset: {
      borderColor: theme.colors.border,
      borderRadius: theme.radii.md,
      borderWidth: 1,
      marginBottom: theme.spacing.md,
      padding: theme.spacing.md,
    } as Style,
  });
  return (
    <FieldSet
      {...getPdfPrimitiveProps(primitiveProps)}
      name={name}
      style={mergePdfStyles(styles.fieldset, style)}
    >
      <NativeFieldLabel style={labelStyle}>{label}</NativeFieldLabel>
      {children}
    </FieldSet>
  );
}

export function PdfTextInputField({
  label,
  description,
  align,
  multiline,
  password,
  noSpell,
  format,
  fontSize,
  maxLength,
  lines = multiline ? 4 : 1,
  style,
  labelStyle,
  inputStyle,
  ...fieldProps
}: PdfTextInputFieldProps) {
  const theme = usePdfTheme();
  const safeLines = clampPdfNumber(lines, multiline ? 4 : 1, 1, 12);
  const styles = StyleSheet.create({
    root: { flex: 1, marginBottom: theme.spacing.sm } as Style,
    input: {
      borderColor: theme.colors.border,
      borderRadius: theme.radii.sm,
      borderWidth: 1,
      color: theme.colors.foreground,
      fontFamily: theme.typography.fontFamily,
      fontSize: fontSize ?? theme.typography.sm,
      minHeight: safeLines * 18,
      padding: 6,
      width: "100%",
    } as Style,
    description: createPdfTextStyle(theme, { size: "xs", tone: "muted" }),
  });

  return (
    <View style={mergePdfStyles(styles.root, style)}>
      <NativeFieldLabel style={labelStyle}>{label}</NativeFieldLabel>
      <TextInput
        {...getNativeFieldProps(fieldProps)}
        align={align}
        multiline={multiline}
        password={password}
        noSpell={noSpell}
        format={format}
        fontSize={fontSize}
        maxLength={maxLength}
        style={mergePdfStyles(styles.input, inputStyle)}
      />
      {isPdfNodeEmpty(description) ? null : (
        <Text style={styles.description}>{formatPdfValue(description)}</Text>
      )}
    </View>
  );
}

export function PdfCheckboxInputField({
  label,
  checked,
  backgroundColor,
  borderColor,
  onState,
  offState,
  xMark,
  style,
  labelStyle,
  checkboxStyle,
  ...fieldProps
}: PdfCheckboxInputFieldProps) {
  const theme = usePdfTheme();
  const styles = StyleSheet.create({
    row: {
      alignItems: "center",
      flexDirection: "row",
      gap: 6,
      marginBottom: theme.spacing.sm,
    } as Style,
    checkbox: {
      height: 12,
      width: 12,
    } as Style,
    label: createPdfTextStyle(theme, { size: "sm" }),
  });

  return (
    <View style={mergePdfStyles(styles.row, style)}>
      <Checkbox
        {...getNativeFieldProps(fieldProps)}
        checked={checked}
        backgroundColor={backgroundColor}
        borderColor={borderColor}
        onState={onState}
        offState={offState}
        xMark={xMark}
        style={mergePdfStyles(styles.checkbox, checkboxStyle)}
      />
      {isPdfNodeEmpty(label) ? null : (
        <Text style={mergePdfStyles(styles.label, labelStyle)}>
          {formatPdfValue(label)}
        </Text>
      )}
    </View>
  );
}

export function PdfSelectField({
  label,
  select = [],
  sort,
  edit,
  multiSelect,
  noSpell,
  style,
  labelStyle,
  inputStyle,
  ...fieldProps
}: PdfSelectFieldProps) {
  const theme = usePdfTheme();
  const styles = StyleSheet.create({
    root: { flex: 1, marginBottom: theme.spacing.sm } as Style,
    input: {
      borderColor: theme.colors.border,
      borderRadius: theme.radii.sm,
      borderWidth: 1,
      color: theme.colors.foreground,
      fontFamily: theme.typography.fontFamily,
      fontSize: theme.typography.sm,
      minHeight: 24,
      padding: 4,
      width: "100%",
    } as Style,
  });
  const props = {
    ...getNativeFieldProps(fieldProps),
    select,
    sort,
    edit,
    multiSelect,
    noSpell,
    style: mergePdfStyles(styles.input, inputStyle),
  } as React.ComponentProps<typeof Select>;

  return (
    <View style={mergePdfStyles(styles.root, style)}>
      <NativeFieldLabel style={labelStyle}>{label}</NativeFieldLabel>
      <Select {...props} />
    </View>
  );
}

export function PdfListInputField(props: PdfListInputFieldProps) {
  const {
    label,
    select = [],
    sort,
    edit,
    multiSelect,
    noSpell,
    style,
    labelStyle,
    inputStyle,
    ...fieldProps
  } = props;
  const theme = usePdfTheme();
  const styles = StyleSheet.create({
    root: { flex: 1, marginBottom: theme.spacing.sm } as Style,
    input: {
      borderColor: theme.colors.border,
      borderRadius: theme.radii.sm,
      borderWidth: 1,
      color: theme.colors.foreground,
      fontFamily: theme.typography.fontFamily,
      fontSize: theme.typography.sm,
      minHeight: 56,
      padding: 4,
      width: "100%",
    } as Style,
  });
  const listProps = {
    ...getNativeFieldProps(fieldProps),
    select,
    sort,
    edit,
    multiSelect,
    noSpell,
    style: mergePdfStyles(styles.input, inputStyle),
  } as React.ComponentProps<typeof ReactPdfList>;

  return (
    <View style={mergePdfStyles(styles.root, style)}>
      <NativeFieldLabel style={labelStyle}>{label}</NativeFieldLabel>
      <ReactPdfList {...listProps} />
    </View>
  );
}

/**
 * PDF Theme — shared theme tokens and helpers for edbn/ui PDF components.
 *
 * @registryTitle PDF Theme
 * @registryDescription Theme provider, default tokens, and style helpers for PDF components.
 * @registryVariant pdf
 * @registryType registry:lib
 */

import * as React from "react";
import type {
  Bookmark,
  HitSlop,
  HyphenationCallback,
  Style,
} from "@react-pdf/types";

// ---- TYPES -----------------------------------------------------------------

export interface PdfTheme {
  colors: {
    background: string;
    foreground: string;
    mutedForeground: string;
    border: string;
    primary: string;
    primaryForeground: string;
    muted: string;
    destructive: string;
    warning: string;
    success: string;
  };
  spacing: {
    page: number;
    section: number;
    gap: number;
    sm: number;
    md: number;
    lg: number;
  };
  radii: {
    sm: number;
    md: number;
    lg: number;
  };
  typography: {
    fontFamily: string;
    monoFontFamily: string;
    xs: number;
    sm: number;
    base: number;
    lg: number;
    xl: number;
    xxl: number;
  };
}

export type PdfStyleInput = Style | PdfStyleInput[] | null | undefined | false;

export type PdfTextSize = "xs" | "sm" | "base" | "lg" | "xl" | "xxl";
export type PdfTextTone =
  | "default"
  | "muted"
  | "primary"
  | "destructive"
  | "warning"
  | "success";
export type PdfTextWeight = "normal" | "medium" | "bold";
export type PdfTextAlign = "left" | "center" | "right";
export type PdfBookmark = Bookmark;
export type PdfHitSlop = HitSlop;
export type PdfHyphenationCallback = HyphenationCallback;

export interface PdfTextStyleOptions {
  size?: PdfTextSize;
  tone?: PdfTextTone;
  weight?: PdfTextWeight;
  align?: PdfTextAlign;
  color?: string;
  fontFamily?: string;
  fontSize?: number;
  lineHeight?: number;
  marginBottom?: number;
}

export interface PdfPrimitiveProps {
  id?: string;
  bookmark?: PdfBookmark;
  debug?: boolean;
  fixed?: boolean;
  break?: boolean;
  minPresenceAhead?: number;
}

export interface PdfFlowProps extends PdfPrimitiveProps {
  wrap?: boolean;
}

export interface PdfTextRenderProps {
  pageNumber: number;
  totalPages: number;
  subPageNumber: number;
  subPageTotalPages: number;
}

export interface PdfViewRenderProps {
  pageNumber: number;
  subPageNumber: number;
}

export interface PdfAdvancedTextProps extends PdfFlowProps {
  render?: (props: PdfTextRenderProps) => React.ReactNode;
  hyphenationCallback?: PdfHyphenationCallback;
  orphans?: number;
  widows?: number;
}

export interface PdfAdvancedLinkProps extends PdfFlowProps {
  hitSlop?: PdfHitSlop;
}

// ---- DEFAULT THEME ---------------------------------------------------------

export const defaultPdfTheme: PdfTheme = {
  colors: {
    background: "#ffffff",
    foreground: "#111827",
    mutedForeground: "#6b7280",
    border: "#d1d5db",
    primary: "#2563eb",
    primaryForeground: "#ffffff",
    muted: "#f3f4f6",
    destructive: "#dc2626",
    warning: "#b45309",
    success: "#15803d",
  },
  spacing: {
    page: 36,
    section: 16,
    gap: 10,
    sm: 6,
    md: 10,
    lg: 16,
  },
  radii: {
    sm: 4,
    md: 7,
    lg: 10,
  },
  typography: {
    fontFamily: "Helvetica",
    monoFontFamily: "Courier",
    xs: 8,
    sm: 9,
    base: 10.5,
    lg: 13,
    xl: 18,
    xxl: 28,
  },
};

// ---- CONTEXT ---------------------------------------------------------------

const PdfThemeContext = React.createContext<PdfTheme>(defaultPdfTheme);

export interface PdfThemeProviderProps {
  theme?: Partial<PdfTheme>;
  children: React.ReactNode;
}

function mergeTheme(theme?: Partial<PdfTheme>): PdfTheme {
  if (!theme) return defaultPdfTheme;
  return {
    colors: { ...defaultPdfTheme.colors, ...theme.colors },
    spacing: { ...defaultPdfTheme.spacing, ...theme.spacing },
    radii: { ...defaultPdfTheme.radii, ...theme.radii },
    typography: { ...defaultPdfTheme.typography, ...theme.typography },
  };
}

export function PdfThemeProvider({ theme, children }: PdfThemeProviderProps) {
  const resolvedTheme = React.useMemo(() => mergeTheme(theme), [theme]);
  return (
    <PdfThemeContext.Provider value={resolvedTheme}>
      {children}
    </PdfThemeContext.Provider>
  );
}

export function usePdfTheme(): PdfTheme {
  return React.useContext(PdfThemeContext) ?? defaultPdfTheme;
}

// ---- STYLE HELPERS ---------------------------------------------------------

export function mergePdfStyles(...styles: PdfStyleInput[]): Style[] {
  return styles.flatMap((style): Style[] => {
    if (!style) return [];
    if (Array.isArray(style)) return mergePdfStyles(...style);
    return [style];
  });
}

export function getPdfPrimitiveProps({
  break: pageBreak,
  id,
  bookmark,
  debug,
  fixed,
  minPresenceAhead,
}: PdfPrimitiveProps = {}) {
  return {
    id,
    bookmark,
    debug,
    fixed,
    break: pageBreak,
    minPresenceAhead,
  };
}

export function getPdfFlowProps({
  wrap,
  ...primitiveProps
}: PdfFlowProps = {}) {
  return {
    ...getPdfPrimitiveProps(primitiveProps),
    wrap,
  };
}

export function getToneColor(theme: PdfTheme, tone?: string): string {
  switch (tone) {
    case "primary":
      return theme.colors.primary;
    case "muted":
      return theme.colors.mutedForeground;
    case "destructive":
      return theme.colors.destructive;
    case "warning":
      return theme.colors.warning;
    case "success":
      return theme.colors.success;
    default:
      return theme.colors.foreground;
  }
}

export function getPdfFontWeight(weight?: PdfTextWeight): 400 | 600 | 700 {
  if (weight === "bold") return 700;
  if (weight === "medium") return 600;
  return 400;
}

export function createPdfTextStyle(
  theme: PdfTheme,
  {
    size = "sm",
    tone = "default",
    weight = "normal",
    align = "left",
    color,
    fontFamily,
    fontSize,
    lineHeight = 1.45,
    marginBottom = 0,
  }: PdfTextStyleOptions = {}
): Style {
  return {
    color: color ?? getToneColor(theme, tone),
    fontFamily: fontFamily ?? theme.typography.fontFamily,
    fontSize: fontSize ?? theme.typography[size],
    fontWeight: getPdfFontWeight(weight),
    lineHeight,
    marginBottom,
    textAlign: align,
  } as Style;
}

export function isPdfNodeEmpty(value: React.ReactNode): boolean {
  if (value == null || typeof value === "boolean") return true;
  if (typeof value === "string") return value.trim().length === 0;
  if (Array.isArray(value)) return value.every(isPdfNodeEmpty);
  return false;
}

export function formatPdfValue(
  value: unknown,
  emptyValue: React.ReactNode = ""
): React.ReactNode {
  if (value == null) return emptyValue;
  if (React.isValidElement(value)) return value;
  if (Array.isArray(value)) {
    if (value.some(React.isValidElement)) {
      const nodes = value.filter(
        (item) => !isPdfNodeEmpty(item as React.ReactNode)
      );
      return nodes.length > 0 ? nodes : emptyValue;
    }
    const values = value
      .map((item) => formatPdfValue(item, ""))
      .filter((item) => !isPdfNodeEmpty(item as React.ReactNode));
    return values.length > 0 ? values.join(", ") : emptyValue;
  }
  if (value instanceof Date) {
    return Number.isNaN(value.getTime())
      ? emptyValue
      : value.toISOString().slice(0, 10);
  }
  if (typeof value === "number") {
    return Number.isFinite(value) ? String(value) : emptyValue;
  }
  if (typeof value === "bigint") return value.toString();
  if (typeof value === "boolean") return value ? "Yes" : "No";
  if (typeof value === "string") {
    return value.trim().length > 0 ? value : emptyValue;
  }
  return emptyValue;
}

export function normalizePdfString(value: string | null | undefined): string {
  return value?.trim() ?? "";
}

export function clampPdfNumber(
  value: number | undefined,
  fallback: number,
  min = 0,
  max = Number.MAX_SAFE_INTEGER
): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
  return Math.min(Math.max(value, min), max);
}

export function resolvePdfSize(
  value: number | string | undefined
): number | string | undefined {
  if (typeof value === "number") {
    return Number.isFinite(value) && value > 0 ? value : undefined;
  }
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed.length > 0 ? trimmed : undefined;
  }
  return undefined;
}
